 rows=reconciliation_rows(filters);cols=[col("name","Allocation Run","Link","Payroll Allocation Run",170,True),col("payroll_entry","Payroll Entry","Link","Payroll Entry",170,True),col("company","Company","Link","Company",150),col("posting_date","Posting Date","Date",width=110),col("total_allocated_cost","Allocated Cost","Currency",width=135),col("journal_debit","Journal Debit","Currency",width=125),col("journal_credit","Journal Credit","Currency",width=125),col("result_vs_gl_difference","Result vs GL","Currency",width=120),col("commitment_status","Commitment","Data",width=120),col("liability_reconciliation_status","Liability","Data",width=120),col("payment_reconciliation_status","Payment","Data",width=120),col("reconciliation_status","Status","Data",width=120)];cards=[summary(len(rows),"Runs","Int"),summary(sum(x.reconciliation_status=="Matched" for x in rows),"Matched","Int","Green"),summary(sum(x.reconciliation_status!="Matched" for x in rows),"Open","Int","Orange")];return cols,rows,None,None,cards
